//! Generates `crates/protocol/src/generated/mod.rs` from
//! `packages/contracts/schema/*.schema.json` with typify.
//!
//! Usage: `cargo run -p reopen-protocol-codegen [-- --check]`.
//! `--check` exits non-zero when the committed output differs.

use std::fs;
use std::io::Write as _;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use typify::{TypeSpace, TypeSpaceSettings};

const HEADER: &str = "// @generated by reopen-protocol-codegen from packages/contracts/schema.\n\
// Do not edit by hand; run `pnpm contracts:generate`.\n\n";

fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn schema_files(dir: &Path) -> Result<Vec<PathBuf>, String> {
    let mut files: Vec<PathBuf> = fs::read_dir(dir)
        .map_err(|e| format!("reading {}: {e}", dir.display()))?
        .filter_map(Result::ok)
        .map(|entry| entry.path())
        .filter(|path| path.to_string_lossy().ends_with(".schema.json"))
        .collect();
    files.sort();
    Ok(files)
}

fn generate(schema_dir: &Path) -> Result<String, String> {
    let mut settings = TypeSpaceSettings::default();
    settings.with_struct_builder(false);
    settings.with_derive("PartialEq".to_owned());
    let mut space = TypeSpace::new(&settings);

    for path in schema_files(schema_dir)? {
        let text =
            fs::read_to_string(&path).map_err(|e| format!("reading {}: {e}", path.display()))?;
        let schema: schemars::schema::RootSchema =
            serde_json::from_str(&text).map_err(|e| format!("parsing {}: {e}", path.display()))?;
        space
            .add_root_schema(schema)
            .map_err(|e| format!("converting {}: {e}", path.display()))?;
    }

    let file: syn::File =
        syn::parse2(space.to_stream()).map_err(|e| format!("parsing generated tokens: {e}"))?;
    Ok(format!("{HEADER}{}", prettyplease::unparse(&file)))
}

fn run() -> Result<bool, String> {
    let check = std::env::args().any(|arg| arg == "--check");
    let root = repo_root();
    let output = root.join("crates/protocol/src/generated/mod.rs");
    let generated = generate(&root.join("packages/contracts/schema"))?;

    if check {
        let current = fs::read_to_string(&output).unwrap_or_default();
        return Ok(current == generated);
    }
    fs::write(&output, generated).map_err(|e| format!("writing {}: {e}", output.display()))?;
    Ok(true)
}

fn main() -> ExitCode {
    let mut stderr = std::io::stderr();
    match run() {
        Ok(true) => ExitCode::SUCCESS,
        Ok(false) => {
            let _ = writeln!(
                stderr,
                "crates/protocol/src/generated is out of date; run `pnpm contracts:generate`."
            );
            ExitCode::FAILURE
        }
        Err(message) => {
            let _ = writeln!(stderr, "reopen-protocol-codegen: {message}");
            ExitCode::FAILURE
        }
    }
}
